with filtered as (select id, customer_id, account_type, opened_date, status, substring(account_type, 1, 4) as account_type_prefix, coalesce(balance, 0) as balance_filled from accounts where customer_id is not null and balance between 50000 and 66000) select * from (select *, row_number() over (partition by status order by opened_date desc nulls first, id) as dedup_rank from filtered) ranked where dedup_rank = 1
